using UnityEngine;using UnityEditor;
public sealed class NeonTextureScaleWindow:EditorWindow {
 [MenuItem("Editor/Texturas de neón",false,2024)]public static void Open(){GetWindow<NeonTextureScaleWindow>("Texturas de neón").Show();}
 void OnGUI(){var settings=DungeonVisualSettings.Current;if(settings==null){EditorGUILayout.HelpBox("No se encontró DungeonVisualSettings.",MessageType.Error);return;}EditorGUILayout.LabelField("TAMAÑO DE CUADRÍCULAS — JUEGO ORIGINAL",EditorStyles.boldLabel);EditorGUILayout.HelpBox("1 = tamaño anterior · 2 = cuadros del doble de tamaño · 0.5 = cuadros más pequeños. Cambia durante Play y se guarda en el asset. No cambia el tamaño del mapa ni las colisiones.",MessageType.Info);var so=new SerializedObject(settings);so.Update();EditorGUILayout.PropertyField(so.FindProperty("wallGridScale"),new GUIContent("Paredes"));EditorGUILayout.PropertyField(so.FindProperty("floorGridScale"),new GUIContent("Suelo"));EditorGUILayout.PropertyField(so.FindProperty("ceilingTextureScale"),new GUIContent("Techo"));EditorGUILayout.BeginHorizontal();foreach(float scale in new[]{1f,2f,3f})if(GUILayout.Button(scale==1?"Restaurar 1×":scale+"× paredes y suelo")){so.FindProperty("wallGridScale").floatValue=scale;so.FindProperty("floorGridScale").floatValue=scale;}EditorGUILayout.EndHorizontal();if(so.ApplyModifiedProperties()){EditorUtility.SetDirty(settings);AssetDatabase.SaveAssetIfDirty(settings);}if(GUILayout.Button("Ver asset en Inspector")){Selection.activeObject=settings;EditorGUIUtility.PingObject(settings);}}
}
